\": 50, \"memory\": 24.625, \"accepted\": true, \"submitStatus\": \"ACCEPTED\"}]}','2026-01-04 16:20:15','2026-01-04 16:20:15','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int a = scanner.nextInt();\n        int b = scanner.nextInt();\n        System.out.println(a+b);\n        // 在这里编写你的代码\n    }\n}','java','ACCEPTED',NULL),(67,12,1,2,'{\"total\": 2, \"totalPass\": 2, \"checkPoints\": [{\"time\": 40, \"memory\": 24.625, \"accepted\": true, \"submitStatus\": \"ACCEPTED\"}, {\"time\": 50, \"memory\": 24.75, \"accepted\": true, \"submitStatus\": \"ACCEPTED\"}]}','2026-01-04 17:19:22','2026-01-04 17:19:22','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int a = scanner.nextInt();\n        int b = scanner.nextInt();\n        System.out.println(a + b);\n        // 在这里编写你的代码\n    }\n}','java','ACCEPTED',NULL),(68,12,1,2,'{\"total\": 2, \"totalPass\": 1, \"checkPoints\": [{\"time\": 40, \"memory\": 24.625, \"accepted\": true, \"submitStatus\": \"ACCEPTED\"}, {\"time\": 50, \"memory\": 24.5, \"accepted\": false, \"submitStatus\": \"WA\"}]}','2026-01-04 17:19:35','2026-01-04 17:19:35','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner scanner = new Scanner(System.in);\n        int a = scanner.nextInt();\n        int b = scanner.nextInt();\n        System.out.println(10);\n        // 在这里编写你的代码\n    }\n}','java','WA',NULL),(70,14,1,2,'{\"total\": 2, \"totalPass\": 0, \"checkPoints\": [{\"time\": 0, \"memory\": 0.0, \"accepted\": false, \"submitStatus\": \"TLE\"}, {\"time\": 0, \"memory\": 0.0, \"accepted\": false, \"submitStatus\": \"TLE\"}]}','2026-01-04 21:10:09','2026-01-04 21:10:09','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        List<Integer> list = new ArrayList<>();\n\n        // 1. 直接用 Scanner 循环读取所有整数\n        // 在本地调试时，输入完数字后需要按 Ctrl+D (Mac/Linux) 或 Ctrl+Z (Windows) 来结束输入流\n        // 在 OJ 判题系统里，系统会自动发送结束信号，循环会自动停止\n        while (sc.hasNextInt()) {\n            list.add(sc.nextInt());\n        }\n\n        // 2. 将 List 转为 int[] 数组，方便排序和处理\n        int[] nums = new int[list.size()];\n        for (int i = 0; i < list.size(); i++) {\n            nums[i] = list.get(i);\n        }\n\n        // 3. 执行核心逻辑\n        solution(nums);\n    }\n\n    public static void solution(int[] nums) {\n        int n = nums.length;\n        \n        // 少于3个数没法组三元组，直接结束\n        if (n < 3) return;\n\n        // 核心步骤：必须排序\n        Arrays.sort(nums);\n\n        for (int i = 0; i < n - 2; i++) {\n            // 优化1：如果当前数字大于0，后面不可能凑出0了（因为已经排过序）\n            if (nums[i] > 0) break;\n\n            // 去重1：跳过重复的基准数 i\n            if (i > 0 && nums[i] == nums[i - 1]) continue;\n\n            int left = i + 1;\n            int right = n - 1;\n\n            while (left < right) {\n                int sum = nums[i] + nums[left] + nums[right];\n\n                if (sum == 0) {\n                    // 按照格式输出结果\n                    System.out.println(nums[i] + \" \" + nums[left] + \" \" + nums[right]);\n\n                    // 去重2：跳过重复的 left 和 right\n                    while (left < right && nums[left] == nums[left + 1]) left++;\n                    while (left < right && nums[right] == nums[right - 1]) right--;\n\n                    left++;\n                    right--;\n                } else if (sum < 0) {\n                    left++; // 和太小，需要大一点的数\n                } else {\n                    right--; // 和太大，需要小一点的数\n                }\n            }\n        }\n    }\n}','java','TLE',NULL),(71,14,1,2,'{\"total\": 2, \"totalPass\": 0, \"checkPoints\": [{\"time\": 50, \"memory\": 24.5, \"accepted\": false, \"submitStatus\": \"WA\"}, {\"time\": 40, \"memory\": 24.625, \"accepted\": false, \"submitStatus\": \"WA\"}]}','2026-01-04 21:17:43','2026-01-04 21:17:43','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner in = new Scanner(System.in);\n        List<Integer> list = new ArrayList<>();\n        int time = in.nextInt();\n        for(int i =0;i<time;++i){\n            list.add(in.nextInt());\n        }\n\n        // 2. 将 List 转为 int[] 数组\n        int[] nums = new int[list.size()];\n        for (int i = 0; i < list.size(); i++) {\n            nums[i] = list.get(i);\n        }\n\n        // 3. 执行核心逻辑\n        solution(nums);\n    }\n\n    public static void solution(int[] nums) {\n        int n = nums.length;\n        \n        if (n < 3) return;\n\n        Arrays.sort(nums);\n\n        for (int i = 0; i < n - 2; i++) {\n            if (nums[i] > 0) break;\n            if (i > 0 && nums[i] == nums[i - 1]) continue;\n\n            int left = i + 1;\n            int right = n - 1;\n\n            while (left < right) {\n                int sum = nums[i] + nums[left] + nums[right];\n\n                if (sum == 0) {\n                    System.out.println(nums[i] + \" \" + nums[left] + \" \" + nums[right]);\n\n                    while (left < right && nums[left] == nums[left + 1]) left++;\n                    while (left < right && nums[right] == nums[right - 1]) right--;\n\n                    left++;\n                    right--;\n                } else if (sum < 0) {\n                    left++;\n                } else {\n                    right--;\n                }\n            }\n        }\n    }\n}','java','WA',NULL),(72,14,1,2,'{\"total\": 2, \"totalPass\": 1, \"checkPoints\": [{\"time\": 50, \"memory\": 24.75, \"accepted\": true, \"submitStatus\": \"ACCEPTED\"}, {\"time\": 50, \"memory\": 24.875, \"accepted\": false, \"submitStatus\": \"RE\"}]}','2026-01-04 21:43:02','2026-01-04 21:43:02','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        \n            // 1. 读取输入\n            int n = sc.nextInt(); // 读取数组长度\n            int[] nums = new int[n];\n            for (int i = 0; i < n; i++) {\n                nums[i] = sc.nextInt(); // 读取数组元素\n            }\n            \n            // 2. 核心逻辑\n            List<List<Integer>> result = threeSum(nums);\n            \n            // 3. 输出处理 (新增了判空逻辑)\n            if (result.isEmpty()) {\n                System.out.println(\"null\");\n            } else {\n                for (List<Integer> triple : result) {\n                    System.out.println(triple.get(0) + \" \" + triple.get(1) + \" \" + triple.get(2));\n                }\n            }\n        \n        sc.close();\n    }\n\n    public static List<List<Integer>> threeSum(int[] nums) {\n        List<List<Integer>> ans = new ArrayList<>();\n        int len = nums.length;\n        // 如果数组长度不够3个，直接返回空列表\n        if (nums == null || len < 3) return ans;\n\n        Arrays.sort(nums); // 排序\n\n        for (int i = 0; i < len; i++) {\n            if (nums[i] > 0) break; // 剪枝：如果当前最小的数都大于0，不可能凑成0\n            if (i > 0 && nums[i] == nums[i - 1]) continue; // 去重：跳过重复的第一个数\n\n            int L = i + 1;\n            int R = len - 1;\n\n            while (L < R) {\n                int sum = nums[i] + nums[L] + nums[R];\n                \n                if (sum == 0) {\n                    ans.add(Arrays.asList(nums[i], nums[L], nums[R]));\n                    \n                    // 去重：跳过重复的第二、第三个数\n                    while (L < R && nums[L] == nums[L + 1]) L++; \n                    while (L < R && nums[R] == nums[R - 1]) R--; \n                    \n                    L++;\n                    R--;\n                } else if (sum < 0) {\n                    L++;\n                } else if (sum > 0) {\n                    R--;\n                }\n            }\n        }\n        return ans;\n    }\n}','java','RE',NULL),(73,14,1,2,'{\"total\": 2, \"totalPass\": 1, \"checkPoints\": [{\"time\": 50, \"memory\": 24.5, \"accepted\": true, \"submitStatus\": \"ACCEPTED\"}, {\"time\": 40, \"memory\": 24.5, \"accepted\": false, \"submitStatus\": \"RE\"}]}','2026-01-04 21:43:19','2026-01-04 21:43:19','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        \n            // 1. 读取输入\n            int n = sc.nextInt(); // 读取数组长度\n            int[] nums = new int[n];\n            for (int i = 0; i < n; i++) {\n                nums[i] = sc.nextInt(); // 读取数组元素\n            }\n            \n            // 2. 核心逻辑\n            List<List<Integer>> result = threeSum(nums);\n            \n            // 3. 输出处理 (新增了判空逻辑)\n            if (result.isEmpty()) {\n                System.out.println(\"null\");\n            } else {\n                for (List<Integer> triple : result) {\n                    System.out.println(triple.get(0) + \" \" + triple.get(1) + \" \" + triple.get(2));\n                }\n            }\n        \n        sc.close();\n    }\n\n    public static List<List<Integer>> threeSum(int[] nums) {\n        List<List<Integer>> ans = new ArrayList<>();\n        int len = nums.length;\n        // 如果数组长度不够3个，直接返回空列表\n        if (nums == null || len < 3) return ans;\n\n        Arrays.sort(nums); // 排序\n\n        for (int i = 0; i < len; i++) {\n            if (nums[i] > 0) break; // 剪枝：如果当前最小的数都大于0，不可能凑成0\n            if (i > 0 && nums[i] == nums[i - 1]) continue; // 去重：跳过重复的第一个数\n\n            int L = i + 1;\n            int R = len - 1;\n\n            while (L < R) {\n                int sum = nums[i] + nums[L] + nums[R];\n                \n                if (sum == 0) {\n                    ans.add(Arrays.asList(nums[i], nums[L], nums[R]));\n                    \n                    // 去重：跳过重复的第二、第三个数\n                    while (L < R && nums[L] == nums[L + 1]) L++; \n                    while (L < R && nums[R] == nums[R - 1]) R--; \n                    \n                    L++;\n                    R--;\n                } else if (sum < 0) {\n                    L++;\n                } else if (sum > 0) {\n                    R--;\n                }\n            }\n        }\n        return ans;\n    }\n}','java','RE',NULL),(74,14,1,2,'{\"total\": 2, \"totalPass\": 1, \"checkPoints\": [{\"time\": 50, \"memory\": 24.5, \"accepted\": true, \"submitStatus\": \"ACCEPTED\"}, {\"time\": 60, \"memory\": 24.625, \"accepted\": false, \"submitStatus\": \"RE\"}]}','2026-01-04 21:43:44','2026-01-04 21:43:44','import java.util.*;\n\npublic class Main {\n    public static void main(String[] args) {\n        Scanner sc = new Scanner(System.in);\n        \n            // 1. 读取输入\n            int n = sc.nextInt(); // 读取数组长度\n            int[] nums = new int[n];\n            for (int i = 0; i < n; i++) {\n                nums[i] = sc.nextInt(); // 读取数组元素\n            }\n            \n            // 2. 核心逻辑\n            List<List<Integer>> result = threeSum(nums);\n            \n            // 3. 输出处理 (新增了判空逻辑)\n            if (result.isEmpty()) {\n                System.out.println(\"null\");\n            } else {\n                for (List<Integer> triple : result) {\n                    System.out.println(triple.get(0) + \" \" + triple.get(1) + \" \" + triple.get(2));\n                }\n            }\n        \n    }\n\n    public static List<List<Integer>> threeSum(int[] nums) {\n        List<List<Integer>> ans = new ArrayList<>();\n        int len = nums.length;\n        // 如果数组长度不够3个，直接返回空列表\n        if (nums == null || len < 3) return ans;\n\n        Arrays.sort(nums); // 排序\n\n        for (int i = 0; i < len; i++) {\n            if (nums[i] > 0) break; // 剪枝：如果当前最小的数都大于0，不可能凑成0\n            if (i > 0 && nums[i] == nums[i - 1]) continue; // 去重：跳过重复的第一个数\n\n            int L = i + 1;\n            int R = len - 1;\n\n            while (L < R) {\n                int sum = nums[i] + nums[L] + nums[R];\n                \n               